import React, { useState, useEffect, useContext } from 'react';
import { useForm, Controller } from 'react-hook-form'; // Removed useWatch as it's not used in the refactored version
import { yupResolver } from '@hookform/resolvers/yup';
import * as yup from 'yup';
import axios from 'axios';
import { AuthContext } from '../../context/AuthContext';
import { useLocation, useNavigate } from 'react-router-dom'; // Added useNavigate

// Updated schema for MedicationRequestDTO
const schema = yup.object().shape({
  studentCode: yup.string().required('Child selection is required'),
  medicationName: yup.string().required('Medication name is required'),
  dosage: yup.string().required('Dosage is required'),
  frequency: yup.string().required('Frequency is required'),
  startDate: yup.date().transform((value, originalValue) => { // Ensure date is correctly parsed
    return originalValue ? new Date(originalValue) : null;
  }).required('Start date is required').typeError('Start date must be a valid date'),
  endDate: yup.date().transform((value, originalValue) => {
    return originalValue ? new Date(originalValue) : null;
  }).required('End date is required').typeError('End date must be a valid date').min(
    yup.ref('startDate'),
    "End date can't be before start date"
  ),
  reason: yup.string().required('Reason for medication is required'),
  notes: yup.string().nullable(), // For parent's initial notes, can include doctor's instructions
});

// Renaming component conceptually to MedicationRequestForm, file remains MedicationSubmission.js for now
const MedicationRequestForm = () => {
  const { currentUser } = useContext(AuthContext);
  const location = useLocation();
  const navigate = useNavigate(); // For navigation after actions
  const [children, setChildren] = useState([]);
  const [selectedStudentCode, setSelectedStudentCode] = useState('');
  const [loadingChildren, setLoadingChildren] = useState(false);
  const [requests, setRequests] = useState([]); // Changed from submissions to requests
  const [loadingRequests, setLoadingRequests] = useState(true); // Changed from loading to loadingRequests
  const [submitting, setSubmitting] = useState(false);
  const [showForm, setShowForm] = useState(false);
  
  const { control, handleSubmit, reset, formState: { errors }, setValue } = useForm({
    resolver: yupResolver(schema),
    defaultValues: {
      studentCode: '',
      medicationName: '',
      dosage: '',
      frequency: '',
      startDate: null, // Use null for date inputs
      endDate: null,   // Use null for date inputs
      reason: '',
      notes: '',       // Parent's initial notes
    }
  });

  const onInvalid = (errors) => {
    console.error('MedicationRequestForm: Form validation failed:', errors);
    // Optional: alert('Form validation failed. Please check the fields: ' + Object.keys(errors).join(', '));
  };

  // Effect to fetch children
  useEffect(() => {
    const fetchChildren = async () => {
      if (currentUser && currentUser.userCode) { // Use userCode (parent_code)
        setLoadingChildren(true);
        try {
          const token = localStorage.getItem('token');
          const response = await axios.get(`/api/parent/students`, { 
            headers: { Authorization: `Bearer ${token}` }
          });
          setChildren(response.data || []);
          if (response.data && response.data.length > 0) {
            if (location.state?.studentCode) {
              setSelectedStudentCode(location.state.studentCode);
              setValue('studentCode', location.state.studentCode);
            }
          }
        } catch (error) {
          console.error('Error fetching children:', error);
        } finally {
          setLoadingChildren(false);
        }
      }
    };
    fetchChildren();
  }, [currentUser, location.state, setValue]);

  // Effect to fetch medication requests for the selected child
  useEffect(() => {
    if (selectedStudentCode) {
      fetchMedicationRequests();
    } else {
      setRequests([]);
      setLoadingRequests(false);
    }
  }, [selectedStudentCode]);

  const fetchMedicationRequests = async () => {
    if (!selectedStudentCode) return;
    setLoadingRequests(true);
    try {
      const token = localStorage.getItem('token');
      // Updated API endpoint for fetching requests for a specific student by a parent
      const response = await axios.get(`/api/medication-requests/student/${selectedStudentCode}`, {
        headers: { Authorization: `Bearer ${token}` }
      });
      setRequests(response.data);
    } catch (error) {
      console.error('Error fetching medication requests:', error);
      setRequests([]); // Clear requests on error
    } finally {
      setLoadingRequests(false);
    }
  };

  const onSubmit = async (data) => {
    console.log('MedicationRequestForm: onSubmit triggered.');
    if (!selectedStudentCode) { 
      alert('Please select a child first.');
      return;
    }

    if (!currentUser || !currentUser.userCode) {
      console.error('MedicationRequestForm: Current user or userCode is missing.');
      alert('Error: User information is missing. Please try logging out and logging back in.');
      return;
    }
    
    setSubmitting(true);
    console.log('MedicationRequestForm: Form data received:', data);

    // Prepare DTO, studentCode is already in data from the form
    const requestDTO = {
      studentCode: data.studentCode, // Ensure this is correctly populated
      medicationName: data.medicationName,
      dosage: data.dosage,
      frequency: data.frequency,
      startDate: data.startDate.toISOString().split('T')[0], // Format date to YYYY-MM-DD
      endDate: data.endDate.toISOString().split('T')[0],     // Format date to YYYY-MM-DD
      reason: data.reason,
      notes: data.notes,
    };

    console.log('MedicationRequestForm: Preparing requestDTO for backend:', requestDTO);

    try {
      const token = localStorage.getItem('token');
      // Updated API endpoint for creating a medication request
      await axios.post('/api/medication-requests/', requestDTO, { // Note the trailing slash if your backend expects it
        headers: { 
          Authorization: `Bearer ${token}`,
          'Content-Type': 'application/json' // Explicitly set content type
        }
      });
      
      console.log('MedicationRequestForm: Request submission successful!');
      alert('Medication request submitted successfully!');
      reset({ 
        studentCode: selectedStudentCode, // Keep selected studentCode
        medicationName: '',
        dosage: '',
        frequency: '',
        startDate: null,
        endDate: null,
        reason: '',
        notes: ''
      });
      setShowForm(false);
      fetchMedicationRequests(); // Refresh requests for the current child
    } catch (error) {
      console.error('MedicationRequestForm: Error submitting medication request:', error.response ? error.response.data : error.message, error.stack);
      alert('Error submitting medication request. Please try again. Check console for details.');
    } finally {
      setSubmitting(false);
    }
  };

  const handleChildChange = (e) => {
    const studentCodeValue = e.target.value;
    setSelectedStudentCode(studentCodeValue);
    setValue('studentCode', studentCodeValue);
    if (!studentCodeValue) {
        setShowForm(false);
        setRequests([]); // Clear requests if no child is selected
    }
  };
  
  const handleCancelRequest = async (requestId) => {
    if (!window.confirm("Are you sure you want to cancel this medication request?")) {
        return;
    }
    try {
        const token = localStorage.getItem('token');
        await axios.put(`/api/medication-requests/${requestId}/cancel`, {}, {
            headers: { Authorization: `Bearer ${token}` }
        });
        alert('Medication request cancelled successfully.');
        fetchMedicationRequests(); // Refresh the list
    } catch (error) {
        console.error('Error cancelling medication request:', error.response ? error.response.data : error.message);
        alert('Failed to cancel medication request. ' + (error.response?.data?.message || 'Please try again.'));
    }
  };


  const getStatusBadge = (status) => {
    const statusLower = status ? status.toLowerCase() : 'unknown';
    const badges = {
      pending: 'bg-yellow-100 text-yellow-800',
      approved: 'bg-green-100 text-green-800',
      rejected: 'bg-red-100 text-red-800',
      administered: 'bg-blue-100 text-blue-800',
      cancelled: 'bg-gray-100 text-gray-800' // Added cancelled status
    };
    return badges[statusLower] || 'bg-gray-200 text-gray-900';
  };

  if (loadingChildren && !currentUser) { // Show initial loading if current user or children are loading
    return (
      <div className="min-h-screen flex items-center justify-center">
        <div className="animate-spin rounded-full h-32 w-32 border-b-2 border-indigo-600"></div>
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-gray-50 py-8">
      <div className="max-w-6xl mx-auto px-4 sm:px-6 lg:px-8">
        {/* Header */}
        <div className="bg-white rounded-lg shadow mb-6">
          <div className="px-6 py-4 border-b border-gray-200">
            <div className="flex flex-col sm:flex-row justify-between sm:items-center">
                <div>
                    <h1 className="text-2xl font-bold text-gray-900">Medication Requests</h1>
                    <p className="text-gray-600 mt-1">Submit and manage medication requests for your child</p>
                </div>
                {/* Child Selector */}
                <div className="mt-4 sm:mt-0">
                    <label htmlFor="child-select" className="block text-sm font-medium text-gray-700 mb-1">
                        Select Child
                    </label>
                    <select
                        id="child-select"
                        name="child-select"
                        value={selectedStudentCode} // Changed selectedStudentId to selectedStudentCode
                        onChange={handleChildChange}
                        disabled={loadingChildren || children.length === 0}
                        className="w-full sm:w-auto p-2 border border-gray-300 rounded-md focus:ring-indigo-500 focus:border-indigo-500"
                    >
                        <option value="">{loadingChildren ? 'Loading children...' : '-- Select a Child --'}</option>
                        {children.map(child => (
                        <option key={child.studentCode} value={child.studentCode}>{child.fullName}</option>
                        ))}
                    </select>
                    {errors.studentCode && !selectedStudentCode && (
                        <p className="text-red-600 text-sm mt-1">{errors.studentCode.message}</p>
                    )}
                </div>
            </div>
            {selectedStudentCode && (
                <div className="mt-4 flex justify-end">
                    <button
                        onClick={() => setShowForm(!showForm)}
                        disabled={!selectedStudentCode}
                        className="px-4 py-2 bg-indigo-600 text-white rounded-md hover:bg-indigo-700 disabled:opacity-50"
                    >
                        <i className={`fas ${showForm ? 'fa-times' : 'fa-plus'} mr-2`}></i>
                        {showForm ? 'Cancel New Request' : 'New Medication Request'}
                    </button>
                </div>
            )}
          </div>
        </div>

        {/* Medication Request Form */}
        {showForm && selectedStudentCode && (
          <div className="bg-white rounded-lg shadow mb-6">
            <div className="px-6 py-4 border-b border-gray-200">
              <h2 className="text-xl font-semibold text-gray-900">Submit New Medication Request</h2>
            </div>
            
            <form onSubmit={handleSubmit(onSubmit, onInvalid)} className="p-6 space-y-6">
              {/* Student Code is handled by selection */}
              <Controller
                name="studentCode"
                control={control}
                render={({ field }) => <input type="hidden" {...field} />}
              />

              {/* Medication Name */}
              <div>
                <label htmlFor="medicationName" className="block text-sm font-medium text-gray-700">Medication Name</label>
                <Controller
                  name="medicationName"
                  control={control}
                  render={({ field }) => <input id="medicationName" {...field} className={`mt-1 block w-full p-2 border ${errors.medicationName ? 'border-red-500' : 'border-gray-300'} rounded-md shadow-sm focus:ring-indigo-500 focus:border-indigo-500`} />}
                />
                {errors.medicationName && <p className="text-red-600 text-sm mt-1">{errors.medicationName.message}</p>}
              </div>

              {/* Dosage */}
              <div>
                <label htmlFor="dosage" className="block text-sm font-medium text-gray-700">Dosage</label>
                <Controller
                  name="dosage"
                  control={control}
                  render={({ field }) => <input id="dosage" {...field} className={`mt-1 block w-full p-2 border ${errors.dosage ? 'border-red-500' : 'border-gray-300'} rounded-md shadow-sm focus:ring-indigo-500 focus:border-indigo-500`} />}
                />
                {errors.dosage && <p className="text-red-600 text-sm mt-1">{errors.dosage.message}</p>}
              </div>

              {/* Frequency */}
              <div>
                <label htmlFor="frequency" className="block text-sm font-medium text-gray-700">Frequency</label>
                <Controller
                  name="frequency"
                  control={control}
                  render={({ field }) => <input id="frequency" {...field} placeholder="e.g., Twice a day, Every 4 hours" className={`mt-1 block w-full p-2 border ${errors.frequency ? 'border-red-500' : 'border-gray-300'} rounded-md shadow-sm focus:ring-indigo-500 focus:border-indigo-500`} />}
                />
                {errors.frequency && <p className="text-red-600 text-sm mt-1">{errors.frequency.message}</p>}
              </div>
              
              <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                {/* Start Date */}
                <div>
                  <label htmlFor="startDate" className="block text-sm font-medium text-gray-700">Start Date</label>
                  <Controller
                    name="startDate"
                    control={control}
                    render={({ field }) => <input id="startDate" type="date" {...field} value={field.value ? new Date(field.value).toISOString().split('T')[0] : ''} onChange={e => field.onChange(e.target.valueAsDate)} className={`mt-1 block w-full p-2 border ${errors.startDate ? 'border-red-500' : 'border-gray-300'} rounded-md shadow-sm focus:ring-indigo-500 focus:border-indigo-500`} />}
                  />
                  {errors.startDate && <p className="text-red-600 text-sm mt-1">{errors.startDate.message}</p>}
                </div>

                {/* End Date */}
                <div>
                  <label htmlFor="endDate" className="block text-sm font-medium text-gray-700">End Date</label>
                  <Controller
                    name="endDate"
                    control={control}
                    render={({ field }) => <input id="endDate" type="date" {...field} value={field.value ? new Date(field.value).toISOString().split('T')[0] : ''} onChange={e => field.onChange(e.target.valueAsDate)} className={`mt-1 block w-full p-2 border ${errors.endDate ? 'border-red-500' : 'border-gray-300'} rounded-md shadow-sm focus:ring-indigo-500 focus:border-indigo-500`} />}
                  />
                  {errors.endDate && <p className="text-red-600 text-sm mt-1">{errors.endDate.message}</p>}
                </div>
              </div>

              {/* Reason */}
              <div>
                <label htmlFor="reason" className="block text-sm font-medium text-gray-700">Reason for Medication</label>
                <Controller
                  name="reason"
                  control={control}
                  render={({ field }) => <textarea id="reason" {...field} rows="3" className={`mt-1 block w-full p-2 border ${errors.reason ? 'border-red-500' : 'border-gray-300'} rounded-md shadow-sm focus:ring-indigo-500 focus:border-indigo-500`}></textarea>}
                />
                {errors.reason && <p className="text-red-600 text-sm mt-1">{errors.reason.message}</p>}
              </div>

              {/* Notes (for parent's initial notes, doctor's instructions text) */}
              <div>
                <label htmlFor="notes" className="block text-sm font-medium text-gray-700">Additional Notes (Optional)</label>
                <Controller
                  name="notes"
                  control={control}
                  render={({ field }) => <textarea id="notes" {...field} rows="4" placeholder="Include any specific instructions from the doctor, or other relevant information." className={`mt-1 block w-full p-2 border ${errors.notes ? 'border-red-500' : 'border-gray-300'} rounded-md shadow-sm focus:ring-indigo-500 focus:border-indigo-500`}></textarea>}
                />
                {errors.notes && <p className="text-red-600 text-sm mt-1">{errors.notes.message}</p>}
              </div>
              
              {/* Submit Button */}
              <div className="flex justify-end">
                <button
                  type="button"
                  onClick={() => { setShowForm(false); reset({ studentCode: selectedStudentCode, medicationName: '', dosage: '', frequency: '', startDate: null, endDate: null, reason: '', notes: '' }); }}
                  className="mr-3 px-4 py-2 text-sm font-medium text-gray-700 bg-white border border-gray-300 rounded-md shadow-sm hover:bg-gray-50 focus:outline-none focus:ring-2 focus:ring-offset-2 focus:ring-indigo-500"
                >
                  Cancel
                </button>
                <button
                  type="submit"
                  disabled={submitting}
                  className="px-4 py-2 bg-indigo-600 text-white rounded-md hover:bg-indigo-700 focus:outline-none focus:ring-2 focus:ring-offset-2 focus:ring-indigo-500 disabled:opacity-50"
                >
                  {submitting ? (
                    <svg className="animate-spin -ml-1 mr-3 h-5 w-5 text-white" xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24">
                      <circle className="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" strokeWidth="4"></circle>
                      <path className="opacity-75" fill="currentColor" d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4zm2 5.291A7.962 7.962 0 014 12H0c0 3.042 1.135 5.824 3 7.938l3-2.647z"></path>
                    </svg>
                  ) : 'Submit Request'}
                </button>
              </div>
            </form>
          </div>
        )}

        {/* Display Medication Requests */}
        {selectedStudentCode && (
          <div className="bg-white rounded-lg shadow">
            <div className="px-6 py-4 border-b border-gray-200">
              <h2 className="text-xl font-semibold text-gray-900">Submitted Medication Requests for {children.find(c => c.studentCode === selectedStudentCode)?.fullName || 'Selected Child'}</h2>
            </div>
            <div className="p-6">
              {loadingRequests ? (
                <div className="flex justify-center items-center h-32">
                  <div className="animate-spin rounded-full h-16 w-16 border-b-2 border-indigo-600"></div>
                </div>
              ) : requests.length > 0 ? (
                <ul className="space-y-4">
                  {requests.map(request => (
                    <li key={request.requestId} className="p-4 border border-gray-200 rounded-md shadow-sm">
                      <div className="flex flex-col sm:flex-row justify-between sm:items-start">
                        <div>
                          <h3 className="text-lg font-semibold text-indigo-700">{request.medicationName}</h3>
                          <p className="text-sm text-gray-600">Dosage: {request.dosage} | Frequency: {request.frequency}</p>
                          <p className="text-sm text-gray-600">Dates: {new Date(request.startDate).toLocaleDateString()} - {new Date(request.endDate).toLocaleDateString()}</p>
                          <p className="text-sm text-gray-500 mt-1">Reason: {request.reason}</p>
                          {request.notes && <p className="text-sm text-gray-500 mt-1">Parent Notes: {request.notes}</p>}
                           {/* Display Nurse's notes if available and different from parent's initial notes */}
                          {request.approvedBy && request.notes && <p className="text-sm text-blue-500 mt-1">Nurse Notes: {request.notes}</p>}
                        </div>
                        <div className="mt-2 sm:mt-0 sm:ml-4 flex flex-col items-end">
                            <span className={`px-3 py-1 text-xs font-semibold rounded-full ${getStatusBadge(request.status)}`}>
                                {request.status}
                            </span>
                            {request.status === 'PENDING' && (
                                <button
                                    onClick={() => handleCancelRequest(request.requestId)}
                                    className="mt-2 px-3 py-1 bg-red-500 text-white text-xs rounded-md hover:bg-red-600 focus:outline-none focus:ring-2 focus:ring-red-500 focus:ring-opacity-50"
                                >
                                    Cancel Request
                                </button>
                            )}
                        </div>
                      </div>
                       {request.approvedBy && (
                        <div className="mt-2 pt-2 border-t border-gray-200">
                            <p className="text-xs text-gray-500">
                                Action by Nurse: {request.approvedBy.user.firstName} {request.approvedBy.user.lastName} ({request.approvedBy.nurseCode})
                                on {new Date(request.actionDate).toLocaleString()}
                            </p>
                        </div>
                       )}
                    </li>
                  ))}
                </ul>
              ) : (
                <p className="text-gray-600">No medication requests found for this child.</p>
              )}
            </div>
          </div>
        )}
        {!selectedStudentCode && !loadingChildren && children.length > 0 && (
             <div className="text-center p-8 bg-white rounded-lg shadow">
                <h3 className="text-xl font-semibold text-gray-700">Please select a child to view or submit medication requests.</h3>
            </div>
        )}
         {!loadingChildren && children.length === 0 && currentUser && (
            <div className="text-center p-8 bg-white rounded-lg shadow">
                <h3 className="text-xl font-semibold text-gray-700">No children found for your account.</h3>
                <p className="text-gray-500 mt-2">If you believe this is an error, please contact school administration.</p>
            </div>
        )}

      </div>
    </div>
  );
};

export default MedicationRequestForm; // Changed export name
